const promises = [
  Promise.resolve("Success"),
  Promise.reject("Failed"),
  Promise.resolve("Another success")
];

Promise.allSettled(promises).then(results => {
  console.log(results);
});

// [
//   { status: "fulfilled", value: "Success" },
//   { status: "rejected", reason: "Failed" },
//   { status: "fulfilled", value: "Another success" }
// ]

const fast = new Promise(resolve => {
  setTimeout(() => resolve("Fast"), 1000);
});

const slow = new Promise(resolve => {
  setTimeout(() => resolve("Slow"), 3000);
});

Promise.race([fast, slow]).then(result => {
  console.log(result);
});

// Fast

const first = Promise.reject("Failed");
const second = new Promise(resolve => {
  setTimeout(() => resolve("Success"), 1000);
});
const third = Promise.resolve("Another success");

Promise.any([first, second, third]).then(result => {
  console.log(result);
});

// Another success
// It is the first Promise to fulfill.

const promises = [
  Promise.resolve("A"),
  Promise.reject("B failed"),
  Promise.resolve("C")
];

Promise.all(promises)
  .then(results => console.log(results))
  .catch(error => console.log(error));

// B failed

Promise.allSettled(promises).then(results => {
  console.log(results);
});

// [
//   { status: "fulfilled", value: "A" },
//   { status: "rejected", reason: "B failed" },
//   { status: "fulfilled", value: "C" }
// ]

const failedFast = new Promise((resolve, reject) => {
  setTimeout(() => reject("Failed"), 500);
});

const successSlow = new Promise(resolve => {
  setTimeout(() => resolve("Success"), 1000);
});

Promise.race([failedFast, successSlow])
  .then(result => console.log(result))
  .catch(error => console.log(error));

// Failed

Promise.any([failedFast, successSlow])
  .then(result => console.log(result));

// Success
// race() reacts to the first settled Promise.
// any() waits for the first fulfilled Promise.

const promise1 = Promise.resolve("Success");

const promise2 = new Promise((resolve, reject) => {
  setTimeout(() => reject(new Error("Failed")), 1000);
});

const promise3 = new Promise(resolve => {
  setTimeout(() => resolve("Finished later"), 3000);
});

Promise.all([promise1, promise2, promise3])
  .then(results => console.log(results))
  .catch(error => console.log(error.message));

// Failed
// Promise.all() rejects as soon as promise2 rejects.
// promise3 may still continue running.

const requests = [
  fetch("/api/users"),
  fetch("/api/products"),
  fetch("/api/orders")
];

const results = await Promise.allSettled(requests);

results.forEach(result => {
  if (result.status === "fulfilled") {
    console.log("Success:", result.value);
  } else {
    console.log("Failed:", result.reason);
  }
});

const server1 = fetch("https://server1.example.com/data");
const server2 = fetch("https://server2.example.com/data");
const server3 = fetch("https://server3.example.com/data");

try {
  const response = await Promise.any([
    server1,
    server2,
    server3
  ]);

  console.log("First successful response:", response);
} catch (error) {
  console.log("All servers failed");
}

// Promise.any() succeeds as soon as one server responds successfully.
